/* Global typography.
   Families come from site/tokens.json (fonts.heading = INTL Headline, fonts.body = INTL Text);
   the @font-face rules are generated from tokens.fonts.files. Only the family is set here — sizes,
   weights, colours and spacing stay with each component. */

/* H1-H6 (reset.css only covers h1-h4) */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); }

/* Native controls do not inherit a family on their own. */
button, input, select, textarea, optgroup { font-family: var(--font-body); }

/* Platform classes whose own rule asks for the heading family but which are not H1-H6
   (buttons, labels, eyebrows, nav links, card titles, chips, FAQ questions ...): use INTL Text. */
.bz-eyebrow, .bz-badge, .bz-btn, .bz-herosearch__l, .bz-card__t, .bz-quote__n, .bz-loc__c,
.bz-fcol__h, .bz-form__t, .bz-label, .bz-widget__h, .bz-person__n, .bz-logo__t, .bz-navlabel,
.bz-navitem > a, .bz-chip, .bz-hours caption, .bz-faq summary, .bz-menu-toggle,
.bz-logo__word, .bz-fbrand__n, .bz-stat__v {
  --font-heading: var(--font-body);
}

/* ===== BLOG PAGES (generated; do not edit by hand) =====
   The platform renders /blog without the template's or components' own CSS, so everything the blog listing page
   needs is repeated here: header, footer, banner, cards, FAQ and contact band. The same rules live in the home template
   and in each component; if you change one of those, change this copy too. ===== */

/* ---- header (same as the home template) ---- */
/* Header — sits over the hero on the homepage. */
body [data-bz-node="hdr"]{position:absolute;top:0;left:0;right:0;z-index:60;padding:16px 25px 0 24px;background:transparent}
body [data-bz-node="hdr"]>.bz-container{max-width:none;padding:0}
body [data-bz-node="hdr-row"]{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}
body [data-bz-node="hdr-brand"]{flex:0 0 auto;padding-top:9px;flex-shrink:0}
body [data-bz-node="hdr-brand"] .bz-block{padding:0}
body [data-bz-node="hdr-brand"] .bz-container{padding:0}
body [data-bz-node="hdr-brand"] img{height:34px;width:auto;max-width:none}
body [data-bz-node="hdr-right"]{flex:0 1 auto;display:flex;align-items:center;justify-content:flex-end;min-width:0;height:49px;padding:0 4px 0 16px;box-sizing:border-box;background:rgba(42,39,35,.86);border-radius:6px}
body [data-bz-node="hdr-right"] .bz-block{padding:0}
body [data-bz-node="hdr-right"] .bz-container{padding:0}

/* nav pill */
body [data-bz-node="hdr-menu"] .bz-menu-wrap{flex:0 1 auto}
body [data-bz-node="hdr-menu"] .bz-nav{flex-wrap:nowrap;gap:23px;align-items:center;height:49px;padding:0}
body [data-bz-node="hdr-menu"] .bz-navitem>a{padding:0;font:700 11px/1 var(--font-body);letter-spacing:.09em;text-transform:uppercase;color:#fff;white-space:nowrap;display:inline-flex;align-items:center;gap:6px}
body [data-bz-node="hdr-menu"] .bz-navitem>a:hover{color:var(--accent)}
body [data-bz-node="hdr-menu"] .bz-navitem--has-sub>a::after{content:"";width:12px;height:12px;background:currentColor;-webkit-mask:url(/icons/chevron-down.svg) center/12px no-repeat;mask:url(/icons/chevron-down.svg) center/12px no-repeat}
body [data-bz-node="hdr-menu"] .bz-subnav{top:calc(100% + 14px);left:-16px;min-width:220px;padding:10px 0;background:rgba(32,30,27,.97);border:0;border-radius:6px;box-shadow:0 12px 32px rgba(0,0,0,.35);gap:0}
body [data-bz-node="hdr-menu"] .bz-subnav::before{content:"";position:absolute;left:0;right:0;top:-16px;height:16px}
body [data-bz-node="hdr-menu"] .bz-subnav .bz-navitem>a{display:block;padding:11px 20px;color:#fff;white-space:nowrap}
body [data-bz-node="hdr-menu"] .bz-subnav .bz-navitem>a:hover{background:rgba(255,255,255,.08);color:var(--accent)}

body [data-bz-node="hdr-search"]{margin-left:22px;width:16px;flex:0 0 16px}
body [data-bz-node="hdr-search"] .bz-container{padding:0}
body [data-bz-node="hdr-search"] figure{margin:0}
body [data-bz-node="hdr-search"] a{display:block;width:16px;height:16px}
body [data-bz-node="hdr-search"] img{width:16px;height:16px}
body [data-bz-node="hdr-cta"]{margin-left:14px;flex:0 0 auto}
body [data-bz-node="hdr-cta"] .bz-btns{margin:0}
body [data-bz-node="hdr-cta"] .bz-btn{height:39px;width:122px;min-width:122px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:4px;background:var(--accent);color:#fff;font:700 13px/1 var(--font-body);letter-spacing:.02em;border:0}
body [data-bz-node="hdr-cta"] .bz-btn:hover{background:var(--accent-dark)}

@media (max-width:1100px){
  body [data-bz-node="hdr"]{padding:12px 20px 0}
  body [data-bz-node="hdr-menu"] .bz-menu-toggle{background:rgba(32,30,27,.9);color:#fff;border:0;border-radius:6px;width:44px;height:44px}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open]>.bz-menu{background:#2a2723;border:0;border-radius:6px;left:auto;right:0;top:calc(100% + 8px);min-width:260px;padding:8px 0;box-shadow:0 12px 32px rgba(0,0,0,.35)}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-nav{height:auto;background:none;padding:0;gap:0;flex-direction:column;align-items:stretch}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-navitem>a{padding:13px 20px;display:flex;justify-content:space-between;width:100%;box-sizing:border-box}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav{position:static;display:flex;background:none;box-shadow:none;padding:0}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav::before{display:none}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav .bz-navitem>a{padding-left:36px;font-weight:500}
}
@media (max-width:640px){
  body [data-bz-node="hdr"]{padding:12px 12px 0}
  body [data-bz-node="hdr-row"]{gap:8px;align-items:center}
  body [data-bz-node="hdr-brand"]{padding-top:0;flex:0 1 auto;min-width:0}
  body [data-bz-node="hdr-brand"] img{height:22px;width:auto;max-width:none}
  body [data-bz-node="hdr-right"]{height:44px;padding:0 4px 0 4px;flex:0 0 auto}
  body [data-bz-node="hdr-menu"] .bz-menu-toggle{background:none;width:36px;height:36px}
  body [data-bz-node="hdr-cta"]{margin-left:4px}
  body [data-bz-node="hdr-cta"] .bz-btn{width:auto;min-width:0;height:34px;padding:0 10px;font-size:12px}
  body [data-bz-node="hdr-search"]{display:none}
}

/* ---- footer (same as the site-footer component) ---- */
body [data-bz-node="ft"]{background:#141414;padding:48px 0 0;color:#fff}
body [data-bz-node="ft"] .bz-block{padding:0}
body [data-bz-node="ft"] .bz-container{padding:0}
body [data-bz-node="ft"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ft-row"]>.bz-col{grid-column:auto}
body [data-bz-node="ft-row"]{display:grid;grid-template-columns:371fr 285fr 286fr 246fr;gap:0;padding-bottom:40px;align-items:start}
body [data-bz-node="ft-logo"]{margin-bottom:14px}
body [data-bz-node="ft-logo"] img{height:30px;width:auto}
body [data-bz-node="ft-address"] p{font:400 12.5px/22.5px var(--font-body);color:rgba(255,255,255,.88);margin:0}
body [data-bz-node="ft-address"] a{color:inherit}
body [data-bz-node="ft-address"] p:last-child{margin-top:4px;font-weight:500;color:#fff}
body [data-bz-node="ft-social"]{display:block;margin-top:17px}
body [data-bz-node="ft-social-col"]{display:flex;gap:18px}
body [data-bz-node="ft-social-col"] .bz-block{width:24px}
body [data-bz-node="ft-social-col"] img,body [data-bz-node="ft-social-col"] a{width:24px;height:24px;display:block}
body [data-bz-node="ft-social-col"] .bz-block:hover{opacity:.7}
body [data-bz-node="ft-row"] h3{font:700 11px/1 var(--font-heading);letter-spacing:.22em;text-transform:uppercase;color:#fff;margin:7px 0 18px}
body [data-bz-node="ft-row"] .bz-nav{flex-direction:column;align-items:flex-start;gap:0}
body [data-bz-node="ft-row"] .bz-navitem>a{padding:0;display:block;font:400 12.5px/32px var(--font-body);color:rgba(255,255,255,.9)}
body [data-bz-node="ft-row"] .bz-navitem>a:hover{color:var(--accent)}
body [data-bz-node="ft-bottom"]{display:flex;justify-content:space-between;align-items:center;gap:24px;border-top:1px solid #353535;padding:15px 0 20px;min-height:55px;box-sizing:border-box}
body [data-bz-node="ft-copy"] p{font:400 11px/1.4 var(--font-body);color:rgba(255,255,255,.7);margin:0}
body [data-bz-node="ft-built"]{display:flex;align-items:center;gap:8px;flex:0 0 auto}
body [data-bz-node="ft-built"]>.bz-block{width:auto}
body [data-bz-node="ft-built"] p{font:400 11px/1 var(--font-body);color:rgba(255,255,255,.7);margin:0}
body [data-bz-node="ft-built-logo"] img{width:52px;height:auto}
@media (max-width:1100px){
  body [data-bz-node="ft"]{padding:48px 24px 0}
  body [data-bz-node="ft-row"]{grid-template-columns:1fr 1fr;gap:36px 24px}
  body [data-bz-node="ft-row"]>[data-bz-node="ft-brand"]{grid-column:1/-1}
}
@media (max-width:640px){
  body [data-bz-node="ft"]{padding:40px 20px 0}
  body [data-bz-node="ft-row"]{grid-template-columns:1fr 1fr;gap:32px 16px}
  body [data-bz-node="ft-logo"] img{height:26px}
  body [data-bz-node="ft-bottom"]{flex-direction:column;align-items:flex-start;gap:12px}
}

/* ---- banner (page-banner component) ---- */
body :where([data-bz-node="pb"]) .bz-block{padding:0}
body :where([data-bz-node="pb"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="pb"]>.bz-container{padding-inline:0}

body [data-bz-node="pb"]{position:relative;overflow:hidden;min-height:520px;display:flex;flex-direction:column;justify-content:center;background:#16130f;padding:110px 0 70px}
body [data-bz-node="pb"]::after{content:"";position:absolute;inset:0;background:rgba(0,0,0,.62);z-index:1;pointer-events:none}
body [data-bz-node="pb"]>.bz-container{max-width:var(--container)}
body [data-bz-node="pb-img"]{position:absolute;inset:0;z-index:0}
body [data-bz-node="pb-img"] figure{margin:0;height:100%}
body [data-bz-node="pb-img"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 62%;border-radius:0}
body [data-bz-node="pb-row"]{display:block;position:relative;z-index:2;text-align:center}
body [data-bz-node="pb-crumb"] p{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#fff;margin:0 0 24px}
body [data-bz-node="pb-crumb"] a{color:#fff;text-decoration:none}
body [data-bz-node="pb-crumb"] a:hover{text-decoration:underline}
body [data-bz-node="pb-h"] .bz-headingblock{text-align:center}
body [data-bz-node="pb-h"] h1{font:700 46px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:#fff;margin:0 auto;max-width:900px}
body [data-bz-node="pb-sub"] .bz-text{max-width:640px;margin:24px auto 0}
body [data-bz-node="pb-sub"] p{font:400 14.5px/1.7 var(--font-body);color:rgba(255,255,255,.92);margin:0}
body [data-bz-node="pb-cta"]{margin-top:30px}
body [data-bz-node="pb-cta"] .bz-btns{margin:0;justify-content:center}
body [data-bz-node="pb-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:3px;background:#fff;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none}
body [data-bz-node="pb-cta"] .bz-btn:hover{background:#ececec}
@media (max-width:1100px){body [data-bz-node="pb"]{padding:100px 24px 56px;min-height:460px}body [data-bz-node="pb-h"] h1{font-size:38px}}
@media (max-width:640px){body [data-bz-node="pb"]{padding:92px 20px 44px;min-height:420px}body [data-bz-node="pb-h"] h1{font-size:28px}body [data-bz-node="pb-sub"] p{font-size:13.5px}body [data-bz-node="pb-crumb"] p{margin-bottom:18px}}

/* ---- link cards ---- */
body :where([data-bz-node="lk"]) .bz-block{padding:0}
body :where([data-bz-node="lk"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="lk"]>.bz-container{padding-inline:0}

body [data-bz-node="lk"]{background:var(--paper);padding:96px 0}
body [data-bz-node="lk"]>.bz-container{max-width:var(--container)}
body [data-bz-node="lk-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="lk-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="lk-grid"]{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;align-items:stretch}
body [data-bz-node="lk-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="lk-card-"]{display:flex;flex-direction:column;background:#fff;border:1px solid #e4e4e2;padding:28px 26px 26px;box-sizing:border-box}
body [data-bz-node^="lk-title-"] h3{font:700 15px/1.3 var(--font-heading);letter-spacing:.01em;text-transform:uppercase;color:var(--ink);margin:0 0 14px}
body [data-bz-node^="lk-text-"] .bz-text{max-width:none;margin-bottom:22px}
body [data-bz-node^="lk-text-"] p{font:400 12.5px/1.7 var(--font-body);color:#555;margin:0}
body [data-bz-node^="lk-link-"]{margin-top:auto;padding-top:22px}
body [data-bz-node^="lk-link-"] .bz-btns{margin:0}
body [data-bz-node^="lk-link-"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px;height:auto;min-height:0}
body [data-bz-node^="lk-link-"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body [data-bz-node^="lk-link-"] .bz-btn:hover{color:var(--accent)}
@media (max-width:1100px){body [data-bz-node="lk"]{padding:64px 24px}body [data-bz-node="lk-h"] h2{font-size:30px}body [data-bz-node="lk-grid"]{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){body [data-bz-node="lk"]{padding:48px 20px}body [data-bz-node="lk-h"] h2{font-size:26px}body [data-bz-node="lk-grid"]{grid-template-columns:1fr;gap:14px;margin-top:28px}}

/* ---- contact band ---- */
body :where([data-bz-node="cb"]) .bz-block{padding:0}
body :where([data-bz-node="cb"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="cb"]>.bz-container{padding-inline:0}

body [data-bz-node="cb"]{background:#2a2723;padding:90px 0}
body [data-bz-node="cb"]>.bz-container{max-width:var(--container)}
body [data-bz-node="cb-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px;color:rgba(255,255,255,.8)}
body [data-bz-node="cb-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;color:#fff}
body [data-bz-node="cb-text"] .bz-text{max-width:640px;margin-top:20px}
body [data-bz-node="cb-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;color:rgba(255,255,255,.9)}
body [data-bz-node="cb-btns"]{margin-top:28px}
body [data-bz-node="cb-btns"] .bz-btns{margin:0;gap:12px}
body [data-bz-node="cb-btns"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:3px;background:#fff;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;padding:0 22px}
body [data-bz-node="cb-btns"] .bz-btn:hover{background:#ececec}
@media (max-width:1100px){body [data-bz-node="cb"]{padding:64px 24px}body [data-bz-node="cb-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="cb"]{padding:48px 20px}body [data-bz-node="cb-h"] h2{font-size:26px}}

/* ---- FAQ ---- */
/* ---------- FAQ (shared look) ---------- */
body :where([data-bz-node="fq"]) .bz-block{padding:0}
body :where([data-bz-node="fq"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="fq"]>.bz-container{padding-inline:0;max-width:880px}
body [data-bz-node="fq"]{background:#fff;padding:96px 0}
body [data-bz-node="fq-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="fq-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="fq-list"]{margin-top:36px}
body [data-bz-node="fq-list"] .bz-faqs{display:block;border-top:1px solid #d8d8d6}
body [data-bz-node="fq-list"] .bz-faq{border:0;border-bottom:1px solid #d8d8d6;border-radius:0;background:transparent;padding:0}
body [data-bz-node="fq-list"] .bz-faq summary{list-style:none;position:relative;padding:22px 44px 22px 0;font:700 12.5px/1.5 var(--font-heading);letter-spacing:.02em;text-transform:uppercase;color:var(--ink);cursor:pointer}
body [data-bz-node="fq-list"] .bz-faq summary::-webkit-details-marker{display:none}
body [data-bz-node="fq-list"] .bz-faq summary::after{content:"+";position:absolute;right:6px;top:50%;transform:translateY(-50%);font:400 20px/1 var(--font-body);color:var(--ink)}
body [data-bz-node="fq-list"] .bz-faq[open] summary::after{content:"\2212"}
body [data-bz-node="fq-list"] .bz-faq__a{padding:0 44px 24px 0;margin:0;font:400 13px/1.8 var(--font-body);color:#555}
@media (max-width:1100px){body [data-bz-node="fq"]{padding:64px 24px}body [data-bz-node="fq-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="fq"]{padding:48px 20px}body [data-bz-node="fq-h"] h2{font-size:26px}}

/* ---- Latest posts / More from the blog (the platform's postsList block) ---- */
body :where([data-bz-node="ll"],[data-bz-node="mb"]) .bz-block{padding:0}
body :where([data-bz-node="ll"],[data-bz-node="mb"]) .bz-container{padding:0;max-width:none}
body :is([data-bz-node="ll"],[data-bz-node="mb"])>.bz-container{padding-inline:0;max-width:var(--container)}
body [data-bz-node="ll"]{background:#fff;padding:88px 0 80px}
body [data-bz-node="mb"]{background:var(--paper);padding:88px 0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead{display:flex;flex-wrap:nowrap;align-items:baseline;justify-content:space-between;gap:20px;margin:0 0 36px}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;margin:0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead .bz-btns{margin:0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px;height:auto;min-height:0;display:inline-flex;align-items:center;white-space:nowrap}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead .bz-btn:hover{color:var(--accent)}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;align-items:stretch}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) a.bz-post{display:flex;flex-direction:column;background:#fff;border:1px solid #e4e4e2;border-radius:0;color:var(--ink);text-decoration:none;overflow:hidden}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) a.bz-post:hover{border-color:#c9c9c6}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) a.bz-post img{width:100%;aspect-ratio:2/1;object-fit:cover;border-radius:0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-post .bz-card__body{flex:1 1 auto;padding:22px 24px 12px;gap:0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-post .bz-card__m{font:700 10px/1.4 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:#8a8a88;margin:0 0 14px}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-post .bz-card__t{font:700 15px/1.35 "INTL Headline",system-ui,sans-serif;letter-spacing:.01em;text-transform:uppercase;color:var(--ink);margin:0 0 12px}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-post .bz-post__d{display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;font:400 12.5px/1.75 var(--font-body);color:#666;margin:0}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) a.bz-post::after{content:"Read more \2192";display:block;padding:8px 24px 24px;font:700 11px/1 var(--font-body);letter-spacing:.04em;color:var(--ink)}
body :is([data-bz-node="ll"],[data-bz-node="mb"]) a.bz-post:hover::after{color:var(--accent)}

/* ---- More articles: the platform's own list of every post, showing only the posts beyond the latest six ---- */
main > section.bz-block{padding:0;background:#fff}
main > section.bz-block > .bz-container{max-width:var(--container);padding-inline:0}
main > section.bz-block h1,main > section.bz-block .bz-lede{display:none}
main > section.bz-block ul.bz-bare{display:block;margin:0;padding:0 0 88px}
main > section.bz-block ul.bz-bare:not(:has(li:nth-child(7))){display:none}
main > section.bz-block ul.bz-bare::before{content:"More articles";display:block;font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;font-size:28px;margin-bottom:24px}
main > section.bz-block ul.bz-bare li:nth-child(-n+6){display:none}
main > section.bz-block li.bz-loc{display:block;background:none;border:0;border-top:1px solid #e4e4e2;border-radius:0;padding:18px 0}
main > section.bz-block li.bz-loc:last-child{border-bottom:1px solid #e4e4e2}
main > section.bz-block li.bz-loc a{text-decoration:none;color:var(--ink)}
main > section.bz-block li.bz-loc strong{font:700 15px/1.35 var(--font-heading);text-transform:uppercase;letter-spacing:.01em}
main > section.bz-block li.bz-loc a:hover strong{color:var(--accent)}
main > section.bz-block li.bz-loc .bz-loc__s{display:block;margin-top:8px;font:400 12.5px/1.7 var(--font-body);color:#666}

@media (max-width:1100px){
  body [data-bz-node="ll"],body [data-bz-node="mb"]{padding:64px 24px}
  body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead h2{font-size:30px}
  body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  main > section.bz-block > .bz-container{padding-inline:24px}
}
@media (max-width:640px){
  body [data-bz-node="ll"],body [data-bz-node="mb"]{padding:48px 20px}
  body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead{flex-wrap:wrap;margin-bottom:24px}
  body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-sechead h2{font-size:26px}
  body :is([data-bz-node="ll"],[data-bz-node="mb"]) .bz-grid{grid-template-columns:minmax(0,1fr);gap:16px}
  main > section.bz-block > .bz-container{padding-inline:20px}
}

